var salt = Solution.RandomSalt(16);
Cj.Eq(salt.Length, 16, "salt size");
var h1 = Solution.HashPassword("correct horse", salt);
var h2 = Solution.HashPassword("correct horse", salt);
Cj.Eq(h1, h2, "deterministic for same salt+password");
Cj.True(Solution.VerifyPassword("correct horse", salt, h1), "correct password verifies");
Cj.False(Solution.VerifyPassword("wrong", salt, h1), "wrong password rejected");

var s1 = Solution.RandomSalt(16);
var s2 = Solution.RandomSalt(16);
Cj.False(s1.SequenceEqual(s2), "two salts differ (cryptographic randomness)");
var h1 = Solution.HashPassword("same password", s1);
var h2 = Solution.HashPassword("same password", s2);
Cj.False(h1 == h2, "same password + different salt = different hash (rainbow-table defense)");
